// Why Code: tablas HTML con bucles (citas y métricas) y escape de texto; no hay nodo nativo que lo arme.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $input.first().json;
const n = (k) => Number(d[k]) || 0;
const parse = (v) => (Array.isArray(v) ? v : JSON.parse(v || '[]'));
const citas = parse(d.citas);
const metricas = parse(d.metricas);
const tasa = n('asistieron') + n('ausentes') ? Math.round((100 * n('asistieron')) / (n('asistieron') + n('ausentes'))) : 0;
const estados = { S: ['Asistió', '#137333', '#e6f4ea'], N: ['Ausente', '#c5221f', '#fce8e6'], P: ['Pendiente', '#8c6700', '#fef9e7'],
  R: ['Sin registrar', '#8c6700', '#fef3e0'], C: ['Cancelada', '#5f6368', '#f1f3f4'] };
const nombresOp = { respuesta_agente: 'Respuesta completa del asistente', registrar_agendamiento: 'Agendar cita',
  consultar_disponibilidad: 'Consultar disponibilidad', consultar_agendamientos: 'Consultar citas', consultar_cliente: 'Verificar cliente',
  registrar_cliente: 'Registrar cliente', actualizar_cliente: 'Actualizar cliente', cancelar_agendamiento: 'Cancelar cita',
  reagendar: 'Reagendar cita', actualizar_agendamiento: 'Modificar cita' };
const td = 'padding:8px 12px;border-bottom:1px solid #e0e0e0;font-size:13px;';
const th = (t) => `<th style="padding:10px 12px;text-align:left;font-size:12px;color:#555;">${t}</th>`;
const tarjeta = (v, t, c, bg) => `<td style="background:${bg};padding:14px;border-radius:8px;text-align:center;"><div style="font-size:24px;font-weight:bold;color:${c};">${v}</div><div style="color:#555;font-size:11px;">${t}</div></td>`;
const filas = citas.map((c) => { const [l, col, bg] = estados[c.estado] || [c.estado, '#333', '#eee'];
  return `<tr><td style="${td}">${esc(c.nombre)} ${esc(c.apellido)}</td><td style="${td}">${esc(c.cedula)}</td><td style="${td}">${c.fecha}</td><td style="${td}">${c.hora_inicio}</td><td style="${td}">${esc(c.area)}</td><td style="${td}">${esc(c.descripcion)}</td><td style="${td}text-align:center;"><span style="padding:3px 10px;border-radius:12px;font-size:11px;font-weight:bold;background:${bg};color:${col};">${l}</span></td></tr>`; }).join('');
const segundos = (ms) => (Number(ms) / 1000).toFixed(1) + ' s';
const filasM = metricas.map((m) => `<tr><td style="${td}">${nombresOp[m.operacion] || esc(m.operacion)}</td><td style="${td}text-align:right;">${m.total}</td><td style="${td}text-align:right;">${segundos(m.promedio_ms)}</td><td style="${td}text-align:right;">${segundos(m.p95_ms)}</td><td style="${td}text-align:right;">${m.pct_exito}%</td></tr>`).join('');
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="font-family:Arial,sans-serif;max-width:900px;margin:0 auto;padding:20px;background:#f5f5f5;">'
  + `<div style="background:#1a73e8;padding:24px 30px;"><div style="color:white;font-size:22px;font-weight:bold;">MYF Consultoría</div><div style="color:#c8d8f8;font-size:13px;">Reporte mensual de citas — ${d.mes}</div></div>`
  + '<div style="background:white;border:1px solid #e0e0e0;border-top:none;padding:30px;">'
  + '<table cellspacing="6" style="width:100%;margin-bottom:20px;"><tr>'
  + tarjeta(n('total'), 'Total', '#1a73e8', '#e8f0fe') + tarjeta(n('asistieron'), 'Asistieron', '#137333', '#e6f4ea')
  + tarjeta(n('ausentes'), 'Ausentes', '#c5221f', '#fce8e6') + tarjeta(n('pendientes'), 'Pendientes', '#8c6700', '#fef9e7')
  + tarjeta(n('sin_registrar'), 'Sin registrar', '#8c6700', '#fef3e0') + tarjeta(n('canceladas'), 'Canceladas', '#5f6368', '#f1f3f4')
  + `</tr></table><p style="color:#555;font-size:13px;">Tasa de asistencia (sobre citas con asistencia registrada): <b style="color:#137333;">${tasa}%</b></p>`
  + '<h3 style="color:#333;font-size:15px;">Tiempos de respuesta del asistente</h3>'
  + `<table cellspacing="0" style="width:100%;border-collapse:collapse;"><thead><tr style="background:#f1f3f4;">${th('Operación')}${th('Cantidad')}${th('Promedio')}${th('P95')}${th('Éxito')}</tr></thead><tbody>${filasM || `<tr><td colspan="5" style="${td}text-align:center;color:#888;">Sin métricas este mes</td></tr>`}</tbody></table>`
  + '<h3 style="color:#333;font-size:15px;margin-top:28px;">Detalle de citas</h3>'
  + `<table cellspacing="0" style="width:100%;border-collapse:collapse;"><thead><tr style="background:#f1f3f4;">${th('Cliente')}${th('Cédula')}${th('Fecha')}${th('Hora')}${th('Área')}${th('Descripción')}${th('Estado')}</tr></thead><tbody>${filas || `<tr><td colspan="7" style="${td}text-align:center;color:#888;">No hay citas este mes</td></tr>`}</tbody></table>`
  + '<p style="color:#999;font-size:11px;margin-top:24px;">Generado automáticamente — MYF Consultoría</p></div></body></html>';
return [{ json: { html, asunto: `Reporte mensual de citas — ${d.mes}` } }];
